    return [-(r - item) - item / 2 if r == mn else -(r - item) for r in bins]

def priority(item, bins):
    m = sum(bins) / len(bins)
    return [-abs(r - m) - 0.5 * (r - item) for r in bins]

def priority(item, bins):
    mn = min(bins)
    return [-abs(r - (mn + item)) - 0.05 * (r - item) for r in bins]
